namespace{using U=std::uint32_t;constexpr U sites[]={0x10001420,0x100014c0,0x100038f0,0x100057f0,0x10003a10,0x10003960,0x10003770,0x10003840,0x100037f0,0x10003630,0x100035a0,0x10003540,0x10003570};constexpr U sizes[]={8,4,8,4,4,12,8,12,12,12,16,12,4};
struct Test{std::array<U,24> row{};std::vector<std::uint8_t>data=std::vector<std::uint8_t>(0x100000),stack=std::vector<std::uint8_t>(0x100000);dfre::MissionNetsockPacketMemoryBindings foreign;std::unique_ptr<dfre::MissionNetsockPacketMemory> image;struct F{U site,at,n,id;};std::vector<F>frames;std::vector<std::pair<U,U>>heaps;U serial=0,reads=0,writes=0,calls=0,allocs=0,next=0,find_reads=0;std::uint64_t trace=0;
 Test(const dfre::AssetBytes&raw){foreign.read=[&](U a,U n){U v=0;for(U i=0;i<n;++i)v|=U(*ptr(a+i,1))<<(8*i);return v;};foreign.write=[&](U a,U n,U v){for(U i=0;i<n;++i)*ptr(a+i,1)=std::uint8_t(v>>(8*i));};foreign.resolve=[&](U a,std::size_t n){return ptr(a,n);};image=std::make_unique<dfre::MissionNetsockPacketMemory>(raw,foreign);}
 std::uint8_t*ptr(U a,std::size_t n){if(a>=0x1200000&&std::uint64_t(a-0x1200000)+n<=data.size())return data.data()+a-0x1200000;if(a>=0x3000000&&std::uint64_t(a-0x3000000)+n<=stack.size())return stack.data()+a-0x3000000;throw std::runtime_error("Join fixture address is not mapped");}U get(U a,U n=4){return image->read(a,n);}void put(U a,U v,U n=4){image->write(a,n,v);}U norm(U a){for(auto i=frames.rbegin();i!=frames.rend();++i)if(a>=i->at&&a<i->at+i->n)return 0x30000000+i->id*0x1000+a-i->at;return a;}void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}bool mapped(U a,U n){if(a>=0x10000000&&std::uint64_t(a)+n<=0x1001b000)return true;if(a>=0x1200000&&std::uint64_t(a)+n<=0x1300000)return true;for(auto f:frames)if(a>=f.at&&std::uint64_t(a)+n<=std::uint64_t(f.at)+f.n)return true;return false;}
 U frame(U s){for(auto i=frames.rbegin();i!=frames.rend();++i)if(i->site==s)return i->at;return 0;}
 U make(U s,U n,const std::vector<U>&args){const U a=0x3000000+serial*0x400;frames.push_back({s,a,n,serial++});std::fill_n(ptr(a,n),n,0x5a);U off=s==0x100052e0?0x34:s==0x10005020?0x24:s==0x10004c80?0x20:4;for(U v:args){put(a+off,v);off+=4;}return a;}
 U config()const{return row[3]==0?0:row[3]==2?0x100198ac:0x1200000;}
 void setup(){serial=reads=writes=calls=allocs=find_reads=0;next=0x1280000;trace=1469598103934665603ull;frames.clear();heaps.clear();std::fill(data.begin(),data.end(),0x5a);std::fill_n(image->resolve(0x10019880,0x426),0x426,0);for(auto [a,v]:std::vector<std::pair<U,U>>{{0x10019880,row[1]},{0x10019884,row[2]},{0x100199e4,row[5]},{0x100199ec,row[6]},{0x100199e8,row[7]},{0x10019af0,row[8]},{0x10019c9e,row[9]},{0x100199dc,0x1240000},{0x10019c5c,0x1220000},{0x10019c64,0x10000},{0x10019854,0x1260000},{0x1001985c,0x10000},{0x100096b4,55},{0x100198a8,0x0200007f},{0x100199e0,0x0100007f},{0x1000604c,0x1100100},{0x10006010,0x1100200},{0x10006048,0x1100300},{0x1000605c,0x1100400},{0x10006078,0x1100500},{0x10006064,0x1100600},{0x10006060,0x1100700}})put(a,v);put(0x10019858,row[10],2);put(0x10019c70,0xa5a51234);put(0x1200000,row[4]);put(0x1201000,row[4]);if(row[3]==2)put(config(),row[4]);for(U j=0;j<4;++j){const U v=0x11111111u*(j+1);put(0x12000d0+j*4,v);put(0x12000e0+j*4,v);put(0x12010d0+j*4,v+1);put(0x100199cc+j*4,v);}std::fill_n(ptr(0x1240000,0x21c0),0x21c0,0);for(U i=0;i<32;++i){const U a=0x1240000+i*0x10e;put(a,0x0100007f+i);put(a+4,0x1234+i,2);put(a+0x106,row[11]==3||(row[11]==1&&i==0)||(row[11]==2&&i==1));for(U j=0;j<4;++j)put(a+0xd6+j*4,0x11111111u*(j+1)+(row[12]?0:1));}put(0x1220000,row[13],2);put(0x1220002,row[14],2);if(row[13]==0x1011)std::copy_n(ptr(0x1200000,0x100),0x100,ptr(0x1220004,0x100));else{put(0x1220004,row[15],2);put(0x1220006,row[16],2);put(0x1220008,0x10000);}put(0x10019a80,0,1);}
 dfre::MissionNetsockJoinBindings bindings(){dfre::MissionNetsockJoinBindings b;b.read=[&](U a,U n){event(1);event(norm(a));event(n);if(++reads==row[19]||!mapped(a,n))throw std::runtime_error("Read failure");if((row[17]&64)&&frame(0x100038f0)&&a==frame(0x100038f0)+4&&++find_reads==2)put(a,0x1201000);if((row[17]&256)&&frame(0x10003840)&&a==frame(0x10003840)+8)put(frame(0x10003840)+4,0x0300007f);if((row[17]&1024)&&a==0x100199cc)put(0x12200e4,0xdeadbeef);if((row[17]&1)&&a==0x1240106)put(0x100199dc,0x1244000);if((row[17]&2)&&a==0x12200e4)put(0x100199cc,0xdeadbeef);if((row[17]&4)&&a==0x10019a80)put(0x10019c5c,0x1224000);return get(a,n);};b.write=[&](U a,U n,U v){event(2);event(norm(a));event(n);event(norm(n==4?v:v&((1u<<(8*n))-1)));if(++writes==row[20]||!mapped(a,n))throw std::runtime_error("Store failure");if((row[17]&128)&&a==0x100198ac)put(frames.front().at+4,0x1201000);if((row[17]&2048)&&a==0x100199b0&&frame(0x100037f0))put(frame(0x100037f0)+4,0x0300007f);if((row[17]&32)&&a==0x100199b0)put(0x10019c9e,row[9]^1);put(a,v,n);};b.before_call=[&](U s,const auto&args){event(3);event(s);event(U(args.size()));for(U v:args)event(norm(v));if(++calls==row[21])throw std::runtime_error("Call failure");if((row[17]&512)&&s==0x10003540&&frame(0x100035a0)){const U f=frame(0x100035a0);put(f+4,0x1201000);put(f+8,0x0300007f);put(f+12,0xabcd5678);}bool own=false;for(U q:sites)if(q==s)own=true;const bool full=(row[17]&8)&&(s==0x10003470||s==0x10003a60||s==0x100021d0||s==0x1100400||s==0x1100500||s==0x1100600||s==0x1100700);const bool loop=(row[17]&16)&&(s==0x10005830||s==0x10005020||s==0x10005934||s==0x1000592e||s==0x10005952);if(!own&&!full&&!loop&&s!=0x1100100&&s!=0x1100200&&s!=0x1100300&&s!=0x1000596a&&s!=0x10005916)throw std::runtime_error("Required foreign body");};b.call=[&](U s,const auto&args)->U{if(s==0x10005934){put(args.at(2),0);return 0;}if(s==0x1000592e)return((args.at(0)&255)<<8)|((args[0]>>8)&255);if(s==0x10005952)return args.at(2);if(s==0x1100100)return row[18];if(s==0x1100200){put(0x100199e4,0);put(0x100199e8,1);return 0;}if(s==0x1100300)return 0;if(s==0x1000596a)return row[18];if(s==0x10005916)return 10038;if(s==0x1100400){const U a=next;next+=0x10000;heaps.push_back({a,0x10000});return a;}if(s==0x1100500)return 12345;if(s==0x1100600||s==0x1100700)return 0;throw std::runtime_error("Join required import is not bound");};b.frame=[&](U s,U n,const auto&args){return make(s,n,args);};b.release=[&](U,U,U){frames.pop_back();};b.resolve=[&](U a,std::size_t n){return image->resolve(a,n);};return b;}
};}
int main(int argc,char**argv){if(argc!=2)return 1;std::ifstream file(argv[1],std::ios::binary);dfre::AssetBytes raw((std::istreambuf_iterator<char>(file)),{});Test t(raw);std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;std::istringstream in(line);for(U&v:t.row)if(!(in>>v))return 2;t.setup();auto b=t.bindings();const U op=t.row[0];std::vector<U>args;if(op==0||op==2)args={t.config()};if(op==6)args={0x0100007f};if(op==7||op==8||op==9||op==11)args={0x0100007f,0x5a5a1234};if(op==10)args={t.config(),0x0100007f,0x5a5a1234};const U f=t.make(sites[op],sizes[op],args);bool failed=false;U result=0;try{result=dfre::mission_netsock_join_call(b,sites[op],f);}catch(const std::runtime_error&){failed=true;}if(t.frames.size()!=1)return 3;std::uint64_t state=1469598103934665603ull;const auto hash=[&](U a,U n){const auto*p=t.image->resolve(a,n);for(U i=0;i<n;++i){state^=p[i];state*=1099511628211ull;}};for(auto [a,n]:std::vector<std::pair<U,U>>{{0x10019880,0x426},{0x1200000,0x2000},{0x1220000,0x8000},{0x1240000,0x8000},{0x1260000,0x10000}})hash(a,n);for(auto [a,n]:t.heaps)hash(a,n);if(failed||op==7||op==9)result=0;std::cout<<failed<<' '<<result<<' '<<t.reads<<' '<<t.writes<<' '<<t.calls<<' '<<t.trace<<' '<<state<<'\n';}}
